import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.Crpw6aS5.js";const f=JSON.parse('{"title":"日本五大商社保卫战","description":"2020年疫情恐慌中的逆向投资教科书","frontmatter":{"title":"日本五大商社保卫战","description":"2020年疫情恐慌中的逆向投资教科书"},"headers":[],"relativePath":"02_concepts/japan-investments.md","filePath":"02_concepts/japan-investments.md"}'),o={name:"02_concepts/japan-investments.md"};function h(n,t,s,i,p,d){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="日本五大商社保卫战" tabindex="-1">日本五大商社保卫战 <a class="header-anchor" href="#日本五大商社保卫战" aria-label="Permalink to &quot;日本五大商社保卫战&quot;">​</a></h1><blockquote><p>&quot;当所有人都在逃离时，我们选择了进场。&quot; —— <a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2020年</p></blockquote><p>2020年，新冠疫情引发全球恐慌，航空股崩盘、油价暴跌、国际资本撤离日本……在这场&quot;百年一遇&quot;的危机中，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>做了一个令华尔街震惊的决定：<strong>大笔买入日本五大综合商贸公司</strong>。</p><p>这不是一次普通的逆向投资。这是一场关于<strong>信念、逻辑与耐心的教科书级实践</strong>。</p><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/2019年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">首次披露约60亿美元投资五大商社</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2021年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">增持伊藤忠、三菱、三井至约9%</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2022年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">汇率对冲与未实现收益</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2023年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">总成本1.6万亿日元，市值2.9万亿日元，美元计价收益80亿美元</td></tr></tbody></table><hr><h2 id="一、为什么是日本五大商社" tabindex="-1">一、为什么是日本五大商社 <a class="header-anchor" href="#一、为什么是日本五大商社" aria-label="Permalink to &quot;一、为什么是日本五大商社&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在2019年致股东信中首次披露了这项投资：</p><blockquote><p>&quot;截至2019年底，我们持有五家日本大型商贸公司各约5%的股份。这五家公司分别是：伊藤忠商事、丸红商事、三菱商事、三井物产、住友商事。我们买入的总成本约60亿美元。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2019年致股东信</p></blockquote><p><strong>为什么选择综合商贸公司？</strong></p><ol><li><strong>业务极度多元化</strong>——这五家商社保卫战涵盖能源、金属、食品、物流、化工、航运、金融等数十个行业，本质上是&quot;日本的伯克希尔&quot;</li><li><strong>持续的股票回购</strong>——五家公司都有积极的回购政策，在股价低迷时持续回购</li><li><strong>管理层重视股东回报</strong>——都设定了明确的ROE目标和股东回馈承诺</li><li><strong>估值极低</strong>——当时五家公司的估值普遍低于账面价值，市净率在0.5-0.8倍之间</li></ol><p><strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的标准逻辑：</strong></p><blockquote><p>&quot;这五家公司做的是我理解得了的生意。他们持有大量优质资产，管理层把股东利益放在心上，而且估值非常有吸引力。这和我们投资<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>早期的方式非常相似。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2020年</p></blockquote><hr><h2 id="二、疫情冲击下的-逆向而行" tabindex="-1">二、疫情冲击下的&quot;逆向而行&quot; <a class="header-anchor" href="#二、疫情冲击下的-逆向而行" aria-label="Permalink to &quot;二、疫情冲击下的&quot;逆向而行&quot;&quot;">​</a></h2><p>2020年初，新冠疫情在全球蔓延，日本股市暴跌。日经225指数从24000点跌至16000点，跌幅超过30%。国际资本纷纷撤离。</p><p>就在最恐慌的时刻，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>没有恐慌：</p><blockquote><p>&quot;也许未来十年你会看到比我们更大的灾难，但这是我有生以来最可怕的一次。恐惧心理已经让一些优秀的日本企业股价跌到了不可思议的低位。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2020年致股东信</p></blockquote><p><strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的判断框架：</strong></p><ul><li><strong>业务是否受到永久性损害？</strong> ——不是。五家商社保卫战的业务多元分散，不存在单一行业崩溃导致全面倒闭的风险</li><li><strong>价格是否足够便宜？</strong> ——是。股价已经低于账面价值，安全边际充足</li><li><strong>管理层是否诚信有能力？</strong> ——是。五家都是日本商界的标杆企业</li></ul><hr><h2 id="三、汇率对冲-巴菲特的精妙设计" tabindex="-1">三、汇率对冲：<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的精妙设计 <a class="header-anchor" href="#三、汇率对冲-巴菲特的精妙设计" aria-label="Permalink to &quot;三、汇率对冲：[[巴菲特]]的精妙设计&quot;">​</a></h2><p>2020年<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>面临一个新问题：<strong>日元汇率风险</strong>。日本商社保卫战的收入以日元计价，但伯克希尔的报表以美元计算。如果日元贬值，美元计价的收益就会缩水。</p><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>做了一个经典的对冲安排：</p><blockquote><p>&quot;我们通过发行以日元计价的债券来为这些投资做汇率对冲。这样，我们就锁定了汇率风险，把注意力完全集中在日本企业的基本面分析上。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2020年致股东信</p></blockquote><p><strong>这一操作的意义：</strong></p><ul><li>用日元债券融资购买日元资产——天然对冲</li><li>债券利率极低（日本长期维持零利率/负利率政策）</li><li>不需要在汇率上猜测，专注于企业本身</li></ul><hr><h2 id="四、三年后的结果-价值实现" tabindex="-1">四、三年后的结果：价值实现 <a class="header-anchor" href="#四、三年后的结果-价值实现" aria-label="Permalink to &quot;四、三年后的结果：价值实现&quot;">​</a></h2><p><strong>2023年致股东信</strong>，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>公布了这项投资的完整成绩单：</p><table tabindex="0"><thead><tr><th>指标</th><th>数据</th></tr></thead><tbody><tr><td>总投资成本</td><td>约1.6万亿日元</td></tr><tr><td>当前市值</td><td>约2.9万亿日元</td></tr><tr><td><strong>未实现收益</strong></td><td><strong>约1.3万亿日元（约80亿美元）</strong></td></tr><tr><td>持仓比例</td><td>伊藤忠、丸红、三菱、三井、住商各约9%</td></tr><tr><td>持股时间</td><td>约4年</td></tr></tbody></table><blockquote><p>&quot;这些日本商社保卫战是我们在美国之外最重要的投资之一。他们的管理层说到做到，持续回购股票，提高股东回报率。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2023年致股东信</p></blockquote><hr><h2 id="五、案例启示" tabindex="-1">五、案例启示 <a class="header-anchor" href="#五、案例启示" aria-label="Permalink to &quot;五、案例启示&quot;">​</a></h2><h3 id="_1-危机-危险-恐慌-永久损失" tabindex="-1">1. 危机≠危险，恐慌≠永久损失 <a class="header-anchor" href="#_1-危机-危险-恐慌-永久损失" aria-label="Permalink to &quot;1. 危机≠危险，恐慌≠永久损失&quot;">​</a></h3><p>2020年3月，日本商社保卫战的股价跌至多年低点。大多数投资者选择抛售。<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>选择买入。区别在于：大多数人在看股价，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在看企业价值。</p><h3 id="_2-能力圈不限于国界" tabindex="-1">2. 能力圈不限于国界 <a class="header-anchor" href="#_2-能力圈不限于国界" aria-label="Permalink to &quot;2. 能力圈不限于国界&quot;">​</a></h3><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>长期被批评&quot;不懂科技股，不懂国际股&quot;。但他用行动证明：<strong>能力圈不是地理概念，而是对商业逻辑的理解深度</strong>。日本商社保卫战的商业模式——多元化商贸+资本配置+股东回报——与<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>高度相似，这是<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>能理解的能力圈。</p><h3 id="_3-汇率对冲是成熟投资者的标配" tabindex="-1">3. 汇率对冲是成熟投资者的标配 <a class="header-anchor" href="#_3-汇率对冲是成熟投资者的标配" aria-label="Permalink to &quot;3. 汇率对冲是成熟投资者的标配&quot;">​</a></h3><p>面对非美元资产，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>没有选择&quot;赌汇率&quot;，而是锁定了汇率风险，把所有注意力放在企业价值上。这是专业资本配置思维的体现。</p><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./contrarian.html">逆向投资 (Contrarian)</a> — 在别人恐惧时贪婪</li><li><a href="./safety-margin.html">安全边际 (Safety Margin)</a> — 低于账面价值的价格是安全边际的体现</li><li><a href="./capital-allocation.html">资本配置 (Capital Allocation)</a> — 汇率对冲是资本配置的一部分</li></ul><hr><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=核心总结">2019年：核心总结</a> → <a href="/01_letters/2019年/翻译.html">/01_letters/2019年/翻译</a></li><li><a href="/search.html?q=核心总结">2021年：核心总结</a> → <a href="/01_letters/2021年/翻译.html">/01_letters/2021年/翻译</a></li><li><a href="/search.html?q=核心总结">2022年：核心总结</a> → <a href="/01_letters/2022年/翻译.html">/01_letters/2022年/翻译</a></li><li><a href="/search.html?q=核心总结">2023年：核心总结</a> → <a href="/01_letters/2023年/翻译.html">/01_letters/2023年/翻译</a></li></ul>',49)])])}const c=e(o,[["render",h]]);export{f as __pageData,c as default};
